const assert=(ok,message)=>{if(!ok)throw Error(message);},sha=file=>crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const json=(file,value)=>{fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,JSON.stringify(value,null,2)+'\n');};
const relative=file=>path.relative(ROOT,file).split(path.sep).join('/');
const releaseRoot='https://github.com/unmet23-lab/synk-policy/releases/download/platform-preview-0.4.1-20261012/';
function applySourceOverlay(stage){const files=MANIFEST.files.map(change=>{const source=path.join(ROOT,'platform-performance',path.basename(change.file)),target=path.join(stage,change.file);assert(sha(target)===change.baselineSHA256,'Baseline source differs: '+change.file);assert(sha(source)===change.afterSHA256,'Unreviewed source overlay: '+change.file);fs.copyFileSync(source,target);return change;});return {manifestSHA256:sha(path.join(ROOT,'platform-performance/manifest.json')),files};}
