async function download(url,target,expected){fs.mkdirSync(path.dirname(target),{recursive:true});if(!fs.existsSync(target)){const response=await fetch(url);assert(response.ok,'Download failed '+response.status);await pipeline(Readable.fromWeb(response.body),fs.createWriteStream(target,{flags:'wx'}));}assert(fs.statSync(target).size===expected.bytes&&sha(target)===expected.sha256,'Published baseline bytes differ '+path.basename(target));return target;}
