async function unpack(installer,directory){assert(!fs.existsSync(directory)||fs.readdirSync(directory).length===0,'Preserve existing extraction');fs.mkdirSync(directory,{recursive:true});command(await require('app-builder-lib/out/toolsets/7zip').getPath7za(),['x',installer,'-o'+directory,'-y']);}
function verifyArchive(stage,archive){const asar=require('@electron/asar'),walk=(dir,rel='')=>fs.readdirSync(path.join(dir,rel),{withFileTypes:true}).flatMap(entry=>entry.isDirectory()?walk(dir,path.posix.join(rel,entry.name)):[path.posix.join(rel,entry.name)]).sort(),expected=walk(stage).filter(file=>file!=='synk-install.json'),actual=asar.listPackage(archive).map(file=>file.replaceAll('\\','/').replace(/^\//,'')).filter(file=>!asar.statFile(archive,path.normalize(file)).files).sort();assert(expected.join('\n')===actual.join('\n'),'Archive member list mismatch');for(const file of expected)assert(asar.extractFile(archive,path.normalize(file)).equals(fs.readFileSync(path.join(stage,file))),'Archive source differs '+file);return expected.length;}
async function mac(arch){assert(process.platform==='darwin'&&process.arch===arch,'Matching native macOS required');const packages=structuredClone(MANIFEST.mac[arch].packages),releases=[];for(const item of packages){const file=path.basename(item.installer.path),target=path.join(ROOT,'baseline',arch,file);await download(releaseRoot+file,target,item.installer);item.installer.path=relative(target);releases.push({id:item.client,version:item.version,executableSHA256:item.executable.sha256,asarSHA256:item.asar.sha256,installer:item.installer});}
  const item=await base.buildClient('platform',arch,releases,{version:VERSION,applySourceOverlay});packages.push(item);const report={ok:true,builtAt:new Date().toISOString(),version:VERSION,platform:'darwin',arch,electronVersion:'44.5.1',packages,platformOnly:true,childInstallersUnchanged:true,developerIDSigned:false,adHocSigned:true,notarized:false,requiresInternet:true,requiresDevelopmentServer:false,installed:false,published:false};const directory=path.join(ROOT,'dist',arch,'deliverables');json(path.join(directory,'mac-package-'+arch+'.json'),report);fs.writeFileSync(path.join(directory,'SHA256SUMS-platform-'+arch+'.txt'),item.installer.sha256+'  '+path.basename(item.installer.path)+'\n');console.log(JSON.stringify(report));return report;}
async function windows(){assert(process.platform==='win32'&&process.arch==='x64','Native Windows x64 required');const baseline=MANIFEST.windows.baselineInstaller,source=await download(baseline.url,path.join(ROOT,'baseline/win32/platform-0.4.1.exe'),baseline),unpacked=path.join(ROOT,'baseline/win32/payload');await unpack(source,unpacked);
  const asar=require('@electron/asar'),oldArchive=path.join(unpacked,'resources/app.asar'),frozen=JSON.parse(fs.readFileSync(path.join(ROOT,'source-manifest.json'))).clients.find(c=>c.client==='platform');assert(sha(oldArchive)===frozen.publishedAsarSHA256,'Windows baseline ASAR differs');
  const stage=path.join(ROOT,'stage/win32-x64/platform');assert(!fs.existsSync(stage),'Preserve stage');fs.cpSync(path.join(ROOT,'frozen/platform'),stage,{recursive:true});const sourceOverlay=applySourceOverlay(stage),pkg=JSON.parse(fs.readFileSync(path.join(stage,'package.json')));pkg.version=VERSION;json(path.join(stage,'package.json'),pkg);
  const runtime=JSON.parse(fs.readFileSync(path.join(stage,'runtime.json'))),children=[];
  for(const id of ['world','messenger']){const release=runtime.releases.find(r=>r.id===id&&r.installer),file=path.join(unpacked,'resources/clients',id+'.exe');assert(sha(file)===release.installer.sha256&&fs.statSync(file).size===release.installer.bytes,'Published child differs '+id);children.push({id,release,file});}
  for(const pin of MANIFEST.windows.additionalLegacyPins)assert(!pin.installer&&pin.platform==='win32'&&pin.arch==='x64'&&!runtime.releases.some(r=>r.id===pin.id&&r.version===pin.version),'Invalid additional legacy pin');runtime.releases.push(...MANIFEST.windows.additionalLegacyPins);json(path.join(stage,'runtime.json'),runtime);
  const metadata={clientId:'platform',mode:'development',appId:'im.synk.platform.preview',version:VERSION,arch:'x64',platform:'win32',sourceHash:base.sourceHash(stage)};json(path.join(stage,'synk-install.json'),metadata);
  const out=path.join(ROOT,'dist/win32-x64/platform'),config={appId:metadata.appId,productName:'SYNK Platform Preview',executableName:'SYNKPlatformPreview',electronVersion:'44.5.1',asar:true,npmRebuild:false,forceCodeSigning:false,directories:{app:stage,output:out,buildResources:path.join(stage,'assets')},files:['package.json','runtime.json','src/**','renderer/**','assets/**'],extraResources:[{from:path.join(stage,'synk-install.json'),to:'synk-install.json'},...children.map(item=>({from:item.file,to:'clients/'+item.id+'.exe'}))],artifactName:'SYNK-Platform-Preview-'+VERSION+'-win-x64.${ext}',win:{target:[{target:'nsis',arch:['x64']}],signExecutable:false,icon:path.join(stage,'assets/platform.ico')},nsis:{oneClick:false,perMachine:false,allowElevation:false,allowToChangeInstallationDirectory:false,runAfterFinish:false,deleteAppDataOnUninstall:false,createDesktopShortcut:true,createStartMenuShortcut:true},publish:null};
  const {build,Platform,Arch}=require('electron-builder'),artifacts=await build({projectDir:ROOT,targets:Platform.WINDOWS.createTarget('nsis',Arch.x64),config,publish:'never'}),installer=artifacts.find(file=>file.endsWith('.exe'));assert(installer,'Missing Windows installer');command(await require('app-builder-lib/out/toolsets/7zip').getPath7za(),['t',installer]);
  const delivery=path.join(ROOT,'dist/win32-x64/delivered');await unpack(installer,delivery);const archive=path.join(delivery,'resources/app.asar'),executable=path.join(delivery,'SYNKPlatformPreview.exe');const members=verifyArchive(stage,archive);assert(JSON.stringify(JSON.parse(fs.readFileSync(path.join(delivery,'resources/synk-install.json'))))===JSON.stringify(metadata),'Delivered metadata differs');for(const child of children)assert(sha(path.join(delivery,'resources/clients',child.id+'.exe'))===child.release.installer.sha256,'Delivered child changed');
  const directory=path.join(ROOT,'dist/win32-x64/deliverables'),target=path.join(directory,path.basename(installer));fs.mkdirSync(directory,{recursive:true});fs.copyFileSync(installer,target);
  const report={ok:true,builtAt:new Date().toISOString(),version:VERSION,platform:'win32',arch:'x64',electronVersion:'44.5.1',installer:{path:relative(target),sha256:sha(target),bytes:fs.statSync(target).size},asar:{path:relative(archive),sha256:sha(archive),fileCount:members},executable:{path:relative(executable),sha256:sha(executable)},metadata,sourceOverlay,childInstallersUnchanged:true,additionalLegacyPins:MANIFEST.windows.additionalLegacyPins,children:children.map(({id,release})=>({id,release})),unsignedPreview:true,installerExecuted:false,installedStateTouched:false,published:false};json(path.join(directory,'windows-platform-package.json'),report);fs.writeFileSync(path.join(directory,'SHA256SUMS-platform-win-x64.txt'),report.installer.sha256+'  '+path.basename(installer)+'\n');console.log(JSON.stringify(report));return report;
}
async function main(){const validation=validate(),arg=process.argv[2];if(arg==='--validate-only'){console.log(JSON.stringify(validation));return;}if(/^--arch=(arm64|x64)$/.test(arg))return mac(arg.slice(7));if(arg==='--platform=win32')return windows();throw Error('Use --validate-only, --arch=arm64|x64 or --platform=win32');}
if(require.main===module)main().catch(error=>{console.error(error.stack||error);process.exitCode=1;});
module.exports={validate,applySourceOverlay,MANIFEST,unpack,sha,json};
